.lsb-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.lsb-root,.lsb-root *,.lsb-root *::before,.lsb-root *::after{box-sizing:border-box}
.lsb-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.lsb-root img{display:block;border:0;max-width:none}
.lsb-root [hidden]{display:none!important}
.lsb-root .nS6_124_2287{word-break:break-word;align-content:stretch;display:flex;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;align-items:center;line-height:normal;font-style:normal;position:relative;flex-shrink:0;font-size:18px;white-space:nowrap}
.lsb-root .nS6_124_2288{position:relative;flex-shrink:0;color:var(--wa-text, #fff);width:30px;line-height:21px;white-space:nowrap}
.lsb-root .nS6_124_2289{position:relative;flex-shrink:0;color:var(--wa-point, #c6d4fa);width:12px;line-height:21px;white-space:nowrap}
.lsb-root [data-name="Widget/Sensor Status"] > * > *{margin-left:0;margin-top:0}
.lsb-root [data-node-id$=";13:354"]{border-image:linear-gradient(to bottom,var(--wa-line, #fff) 60%,var(--wa-point, #7cccff) 60%) 1}
.lsb-root{position:absolute;inset:0;background:transparent;z-index:auto;overflow:visible}
.lsb-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.lsb-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.lsb-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.lsb-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.lsb-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.lsb-root[data-theme="light"] .nS6_124_2288{color:var(--wa-text, #10231d)}
.lsb-root[data-theme="light"] .nS6_124_2289{color:var(--wa-point, #0e359f)}
